package io.github.dfauth.trade.utils;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.MapperFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.module.SimpleModule;
import io.github.dfauth.trade.model.LocalDateSerde;
import io.github.dfauth.trade.model.Price;
import lombok.extern.slf4j.Slf4j;
import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.time.LocalDate;
import java.util.Base64;
import java.util.List;
import java.util.Objects;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;
import java.util.zip.ZipOutputStream;

@Slf4j
public class TestData {

    public static final List<Price> EBO = unzipPrices("");
    public static final List<Price> LAU = unzipPrices("");
    public static final List<Price> CSL = unzipPrices("");
    public static final List<Price> PNR = unzipPrices("");
    public static final List<Price> SPZ = unzipPrices("");
    public static final List<Price> EMR = unzipPrices("");
    public static final List<Price> CGC = unzipPrices("");
    public static final List<Price> MP1 = unzipPrices("");
    public static final List<Price> AX1 = unzipPrices("");
    public static final List<Price> PPL = unzipPrices("");
    public static final List<Price> WGX = unzipPrices("");
    public static final List<Price> LBL = unzipPrices("");
    public static final List<Price> ALL = unzipPrices("");

    public static String zip(InputStream stream) {
        try {
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            ZipOutputStream zip = new ZipOutputStream(baos);
            zip.putNextEntry(new ZipEntry("prices"));
            byte[] buffer = new byte[1024];
            int len=0;
            while((len = stream.read(buffer)) > 0) {
                zip.write(buffer, 0, len);
            }
            zip.close();
            return Base64.getEncoder().encodeToString(baos.toByteArray());
        } catch (IOException e) {
            log.error(e.getMessage(), e);
            throw new RuntimeException(e);
        }
    }

    public static List<Price> unzipPrices(String s) {
        try {
            byte[] bytes = Base64.getDecoder().decode(s.getBytes());
            ZipInputStream zip = new ZipInputStream(new ByteArrayInputStream(bytes));
            log.info("reading: "+zip.getNextEntry().getName());
            byte[] buffer = new byte[1024];
            int len;
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            while((len = zip.read(buffer)) > 0) {
                baos.write(buffer,0,len);
            }
            ObjectMapper mapper = new ObjectMapper();
            mapper.configure(MapperFeature.REQUIRE_HANDLERS_FOR_JAVA8_TIMES, false);
            mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);

            SimpleModule module = new SimpleModule();
            module.addDeserializer(LocalDate.class, new LocalDateSerde.Deserializer());
            mapper.registerModule(module);

            return mapper.readValue(baos.toByteArray(), new TypeReference<List<Price>>() {});
        } catch (IOException e) {
            log.error(e.getMessage(), e);
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testIt() {
        try {
            String zipped = zip(Objects.requireNonNull(this.getClass().getResourceAsStream("/price.json")));
            String code = unzipPrices(zipped).getFirst().getCode();
            log.info("public static final List<Price> {} = unzipPrices(\"{}\");", code, zipped);
        } catch (Exception e) {
            log.error(e.getMessage(), e);
            throw new RuntimeException(e);
        }
    }

}
